<template><section class="space-y-5"><div class="flex justify-between"><div><h2 class="text-xl font-bold">Galerie</h2><p class="text-sm text-on-surface-variant">Photos générales ou réservées à une catégorie.</p></div><button class="px-4 py-2 rounded-lg bg-primary text-on-primary" @click="input?.click()">Ajouter des photos</button><input ref="input" class="hidden" type="file" multiple accept="image/*" @change="upload" /></div><div class="flex gap-3 items-center"><select v-model="category" class="border rounded p-2"><option value="">Visible par tous</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select><label><input v-model="enabled" type="checkbox" /> Galerie active</label><button class="border rounded px-3 py-2" @click="save">Enregistrer</button></div><div v-if="loading">Chargement…</div><div v-else class="grid grid-cols-2 md:grid-cols-4 gap-4"><article v-for="p in gallery.photos" :key="p.id" class="border rounded overflow-hidden"><img v-if="photoUrls[p.id]" :src="photoUrls[p.id]" class="aspect-square w-full object-cover" /><div v-else class="aspect-square bg-surface-variant"></div><button class="p-2 text-error text-xs" @click="remove(p.id)">Supprimer</button></article></div></section></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { getGallery,updateGallery,uploadGalleryPhoto,deleteGalleryPhoto,loadGalleryPhotoImage,type Gallery } from '../../api/gallery'; import { listCategories,type GuestCategory } from '../../api/guests'
const id=Number(useRoute().params.id); const input=ref<HTMLInputElement|null>(null); const loading=ref(true); const enabled=ref(true); const category=ref(''); const categories=ref<GuestCategory[]>([]); const gallery=ref<Gallery>({id:0,eventId:id,title:'Galerie',description:null,enabled:true,photos:[]}); const photoUrls=ref<Record<number,string>>({})
async function loadImages(){for(const p of gallery.value.photos){try{photoUrls.value[p.id]=await loadGalleryPhotoImage(id,p.id)}catch{}}}
onMounted(async()=>{try{gallery.value=await getGallery(id);enabled.value=gallery.value.enabled;categories.value=await listCategories(id);await loadImages()}finally{loading.value=false}}); async function save(){gallery.value=await updateGallery(id,{enabled:enabled.value})}; async function upload(e:Event){for(const f of Array.from((e.target as HTMLInputElement).files??[])){const p=await uploadGalleryPhoto(id,f,category.value?Number(category.value):null);gallery.value.photos.push(p);photoUrls.value[p.id]=await loadGalleryPhotoImage(id,p.id)}}; async function remove(pid:number){await deleteGalleryPhoto(id,pid);if(photoUrls.value[pid])URL.revokeObjectURL(photoUrls.value[pid]);delete photoUrls.value[pid];gallery.value.photos=gallery.value.photos.filter(p=>p.id!==pid)}
</script>
